-- Tabel Referensi Lokasi KPPN & Wilayah SAKTI
CREATE TABLE IF NOT EXISTS ref_lokasi (
  id SERIAL PRIMARY KEY,
  kppn_kode VARCHAR(10) NOT NULL,
  kppn_nama VARCHAR(150) NOT NULL,
  kode_lokasi VARCHAR(10) NOT NULL,
  nama_lokasi VARCHAR(150) NOT NULL,
  kode_provinsi VARCHAR(10) NOT NULL,
  kode_kab_kota VARCHAR(10) NOT NULL,
  nama_kab_kota VARCHAR(150) NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_ref_lokasi_kppn_kab UNIQUE (kppn_kode, kode_provinsi, kode_kab_kota)
);

CREATE INDEX IF NOT EXISTS idx_ref_lokasi_prov_kab ON ref_lokasi (kode_provinsi, kode_kab_kota);
CREATE INDEX IF NOT EXISTS idx_ref_lokasi_kppn ON ref_lokasi (kppn_kode);
CREATE INDEX IF NOT EXISTS idx_ref_lokasi_nama_kab ON ref_lokasi (nama_kab_kota);

TRUNCATE TABLE ref_lokasi RESTART IDENTITY CASCADE;

